require_once __DIR__.'/../app/config/database.php';require_once __DIR__.'/../app/helpers/common.php';verify_csrf();$db=pdo_db();$r=$_GET['r']??'home';
if($r==='tari_ajax'){ $q='%'.trim($_GET['q']??'').'%';$st=$db->prepare('SELECT id,nama_tari,provinsi,kategori,gambar FROM tari WHERE nama_tari LIKE ? ORDER BY id DESC LIMIT 12');$st->execute([$q]);header('Content-Type: application/json');echo json_encode($st->fetchAll());exit; }
if($r==='vote'&&$_SERVER['REQUEST_METHOD']==='POST'){ $db->prepare('INSERT INTO vote(tari_id,session_key) VALUES(?,?)')->execute([(int)$_POST['tari_id'],session_id()]);header('Location:?r=home#vote');exit; }
if($r==='checkout'&&$_SERVER['REQUEST_METHOD']==='POST'){ $tot=(int)$_POST['jumlah']*(int)$_POST['harga_tiket'];$db->prepare('INSERT INTO tiket(event_id,nama,email,jumlah,total_harga,status) VALUES(?,?,?,?,?,?)')->execute([(int)$_POST['event_id'],trim($_POST['nama']),trim($_POST['email']),(int)$_POST['jumlah'],$tot,'pending']);header('Location:?r=payment&id='.$db->lastInsertId());exit; }
if($r==='payment_submit'&&$_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)$_GET['id'];$b=upimg('bukti','bukti');$db->prepare('INSERT INTO pembayaran(tiket_id,metode,bukti,status) VALUES(?,?,?,?)')->execute([$id,$_POST['metode'],$b,'menunggu']);$db->prepare("UPDATE tiket SET status='menunggu verifikasi' WHERE id=?")->execute([$id]);header('Location:?r=payment&id='.$id.'&ok=1');exit; }
if($r==='admin_tari_add'&&$_SERVER['REQUEST_METHOD']==='POST'){ $g=upimg('gambar','tari');$db->prepare('INSERT INTO tari(nama_tari,daerah,provinsi,kategori,deskripsi,sejarah,filosofi,properti_tari,pakaian_adat,alat_musik,video_url,gambar,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW())')->execute([$_POST['nama_tari'],$_POST['daerah'],$_POST['provinsi'],$_POST['kategori'],$_POST['deskripsi'],$_POST['sejarah'],$_POST['filosofi'],$_POST['properti_tari'],$_POST['pakaian_adat'],$_POST['alat_musik'],$_POST['video_url'],$g]);header('Location:?r=admin&tari=1');exit; }
if($r==='admin_event_add'&&$_SERVER['REQUEST_METHOD']==='POST'){ $p=upimg('poster','event');$db->prepare('INSERT INTO event(nama_event,lokasi,tanggal,harga_tiket,kuota,deskripsi,poster) VALUES(?,?,?,?,?,?,?)')->execute([$_POST['nama_event'],$_POST['lokasi'],$_POST['tanggal'],(int)$_POST['harga_tiket'],(int)$_POST['kuota'],$_POST['deskripsi'],$p]);header('Location:?r=admin&event=1');exit; }

if($r==='delete_tari'){ $db->prepare('DELETE FROM tari WHERE id=?')->execute([(int)$_GET['id']]);header('Location:?r=admin');exit; }
if($r==='delete_event'){ $db->prepare('DELETE FROM event WHERE id=?')->execute([(int)$_GET['id']]);header('Location:?r=admin');exit; }
if($r==='comment'&&$_SERVER['REQUEST_METHOD']==='POST'){ $db->prepare('INSERT INTO komentar(tari_id,nama,isi) VALUES(?,?,?)')->execute([(int)$_POST['tari_id'],trim($_POST['nama']),trim($_POST['isi'])]);header('Location:?r=home#tari');exit; }
if($r==='fav'&&$_SERVER['REQUEST_METHOD']==='POST'){ $db->prepare('INSERT INTO favorit(tari_id,session_key) VALUES(?,?)')->execute([(int)$_POST['tari_id'],session_id()]);header('Location:?r=home#tari');exit; }

$popular=$db->query('SELECT * FROM tari ORDER BY id DESC LIMIT 6')->fetchAll();$events=$db->query('SELECT * FROM event ORDER BY tanggal ASC LIMIT 6')->fetchAll();$vote=$db->query('SELECT t.id,t.nama_tari,COUNT(v.id) vc FROM tari t LEFT JOIN vote v ON v.tari_id=t.id GROUP BY t.id ORDER BY vc DESC LIMIT 5')->fetchAll();$komentar=$db->query('SELECT k.*,t.nama_tari FROM komentar k JOIN tari t ON t.id=k.tari_id ORDER BY k.id DESC LIMIT 6')->fetchAll();
