r><?php foreach($db->query('SELECT id,nama_tari,provinsi FROM tari ORDER BY id DESC LIMIT 20') as $dt):?><tr><td><?=esc($dt['nama_tari'])?></td><td><?=esc($dt['provinsi'])?></td><td><a href='?r=delete_tari&id=<?=$dt['id']?>' class='btn btn-sm btn-danger'>Hapus</a></td></tr><?php endforeach;?></table><h5>Data Event</h5><table class='table table-sm'><tr><th>Event</th><th>Tanggal</th><th>Aksi</th></tr><?php foreach($db->query('SELECT id,nama_event,tanggal FROM event ORDER BY id DESC LIMIT 20') as $de):?><tr><td><?=esc($de['nama_event'])?></td><td><?=esc($de['tanggal'])?></td><td><a href='?r=delete_event&id=<?=$de['id']?>' class='btn btn-sm btn-danger'>Hapus</a></td></tr><?php endforeach;?></table><h5>Kelola Tiket & User</h5><table class='table table-sm'><tr><th>User</th><th>Event</th><th>Status</th></tr><?php foreach($db->query('SELECT t.nama,t.email,e.nama_event,t.status FROM tiket t JOIN event e ON e.id=t.event_id ORDER BY t.id DESC LIMIT 20') as $tk):?><tr><td><?=esc($tk['nama'])?><br><small><?=esc($tk['email'])?></small></td><td><?=esc($tk['nama_event'])?></td><td><?=esc($tk['status'])?></td></tr><?php endforeach;?></table></main></div></section><?php } ?>
